// Transaction model for credit card and bank reconciliation

export interface TransactionRow {
	id: string;
	family_id: string;
	transaction_date: string;
	vendor_name: string;
	amount: number;
	credit_card_type: string;
	excluded: boolean;
	created_at: string;
	updated_at: string;
}

export interface TransactionInsert {
	family_id: string;
	transaction_date: string;
	vendor_name: string;
	amount: number;
	credit_card_type: string;
	excluded?: boolean;
}

export interface TransactionUpdate {
	transaction_date?: string;
	vendor_name?: string;
	amount?: number;
	credit_card_type?: string;
	excluded?: boolean;
}

export type CreditCardType =
	| 'PC Financial'
	| 'American Express'
	| 'RBC Financial'
	| 'TD Bank'
	| 'Simplii Financial'
	| 'EQ Bank'
	| 'Wealth Simple'; // #{#wsp3a}

export const CREDIT_CARD_TYPES: CreditCardType[] = [
	'PC Financial',
	'American Express',
	'RBC Financial',
	'TD Bank',
	'Simplii Financial',
	'EQ Bank',
	'Wealth Simple' // #{#wsp3a}
];

export interface ParsedTransaction {
	transaction_date: string;
	vendor_name: string;
	amount: number;
}

export interface CSVParseResult {
	transactions: ParsedTransaction[];
	errors: string[];
}

