CREATE OR REPLACE FUNCTION public.set_receipt_family_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if (new.family_id is null) then
    new.family_id := public.ensure_default_family();
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.ensure_default_family()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  uid uuid := auth.uid();
  fam_id uuid;
begin
  if uid is null then
    raise exception 'ensure_default_family() requires auth.uid()';
  end if;

  -- Try to find an active default family
  select fm.family_id into fam_id
  from public.family_members fm
  where fm.user_id = uid and fm.status = 'active' and fm.is_default = true
  limit 1;

  if fam_id is not null then
    return fam_id;
  end if;

  -- If no default, try any active membership
  select fm.family_id into fam_id
  from public.family_members fm
  where fm.user_id = uid and fm.status = 'active'

