/**
 * Deterministic generator for the demo dataset.
 *
 * Pure: given the resolved category ids + the family/user ids, it returns the
 * rows to insert. No DB access here — seed.ts does the inserting. A fixed RNG
 * seed makes every reseed produce the same data, so screenshots stay stable.
 *
 * All receipts have receipt_image_path = null by design (see docs/demo-seed.md).
 */

// Bank/card labels for transactions (mirrors CreditCardType in the app model).
const CREDIT_CARD_TYPES = [
	'PC Financial',
	'American Express',
	'RBC Financial',
	'TD Bank',
	'Simplii Financial',
	'EQ Bank',
	'Wealth Simple'
];

const CARD_NAMES = ['PC Mastercard', 'Amex Cobalt', 'TD Visa Infinite', 'Simplii Visa'];

/**
 * Ordinary-spend catalog. Every category name here matches a row created by the
 * app's create_default_categories RPC, and the three groups of entries below
 * span all three Areas of Importance so the Spending report lights up fully.
 */
type CatalogEntry = { category: string; merchants: string[]; min: number; max: number };

const CATALOG: CatalogEntry[] = [
	// --- Essential ---
	{ category: 'Groceries', merchants: ['Loblaws', 'Metro', 'Sobeys', 'No Frills', 'Costco Wholesale'], min: 40, max: 220 }, // prettier-ignore
	{ category: 'Personal Care', merchants: ['Shoppers Drug Mart', 'Sephora'], min: 15, max: 90 },
	{ category: 'Clothes', merchants: ['Winners', 'H&M', 'Uniqlo'], min: 30, max: 180 },
	{ category: 'Utilities', merchants: ['Toronto Hydro', 'Enbridge Gas', 'Rogers'], min: 60, max: 260 },
	{ category: 'House Maintenance and Repairs', merchants: ['Home Depot', 'Canadian Tire'], min: 25, max: 400 }, // prettier-ignore
	{ category: 'Car - Gas', merchants: ['Petro-Canada', 'Shell', 'Esso'], min: 45, max: 110 },
	{ category: 'Car - Parking', merchants: ['Green P Parking', 'Impark'], min: 8, max: 40 },
	{ category: 'Pharmacy and Medical Tax Deductible', merchants: ['Rexall', 'Shoppers Pharmacy'], min: 12, max: 95 }, // prettier-ignore
	{ category: 'Dental', merchants: ['Bloor West Dental', 'Dr. Chen DDS'], min: 90, max: 450 },
	// --- Priorities ---
	{ category: 'Sports and Fitness', merchants: ['GoodLife Fitness', 'MEC', 'SportChek'], min: 20, max: 160 }, // prettier-ignore
	{ category: 'Kids - Activities', merchants: ['City of Toronto Rec', 'Kumon', 'Swim Academy'], min: 30, max: 220 }, // prettier-ignore
	{ category: 'Investments', merchants: ['Wealthsimple', 'Questrade'], min: 100, max: 800 },
	{ category: 'Banking and Tracking Fees', merchants: ['TD Bank', 'RBC Royal Bank'], min: 4, max: 30 }, // prettier-ignore
	{ category: 'Mortgage', merchants: ['TD Mortgage'], min: 1800, max: 2400 },
	{ category: 'Rental Properties', merchants: ['Skyline Property Mgmt'], min: 200, max: 1200 },
	// --- Other ---
	{ category: 'Meals and Drinks Out', merchants: ['The Keg', 'Boston Pizza', 'Pizzeria Libretto'], min: 25, max: 180 }, // prettier-ignore
	{ category: 'Coffee and Tea', merchants: ['Tim Hortons', 'Starbucks', 'Second Cup'], min: 4, max: 22 }, // prettier-ignore
	{ category: 'Entertainment', merchants: ['Cineplex', 'Netflix', 'Spotify'], min: 10, max: 90 },
	{ category: 'Gifts', merchants: ['Amazon.ca', 'Indigo'], min: 15, max: 150 },
	{ category: 'Donation', merchants: ['Canadian Red Cross', 'SickKids Foundation'], min: 20, max: 200 }, // prettier-ignore
	{ category: 'Travel - Airfare', merchants: ['Air Canada', 'WestJet'], min: 180, max: 900 },
	{ category: 'Travel - Accommodations', merchants: ['Marriott', 'Airbnb'], min: 120, max: 600 }
];

// ---- Row shapes we produce --------------------------------------------------

export type TransactionRecord = {
	id: string;
	family_id: string;
	transaction_date: string;
	vendor_name: string;
	amount: number;
	credit_card_type: string;
	excluded: boolean;
};

export type ReceiptRecord = {
	id: string;
	user_id: string;
	family_id: string;
	receipt_image_path: null;
	transaction_date: string;
	total_amount: number | null;
	tax: number | null;
	merchant_name: string;
	credit_card_name: string | null;
	credit_card_last_4: string | null;
	currency: string;
	exchange_rate_to_cad: number | null;
	matched_transaction_id: string | null;
	suspicious_date: boolean;
	split_group_id: string | null;
	original_filename: null;
};

export type ExpenseCategoryRecord = {
	receipt_id: string;
	category_id: string;
	categorization_source: 'manual' | 'auto';
};

export type DemoData = {
	transactions: TransactionRecord[];
	receipts: ReceiptRecord[];
	expenseCategories: ExpenseCategoryRecord[];
};

export type GeneratorContext = {
	familyId: string;
	ownerId: string;
	memberId: string;
	/** category name (lowercased) -> category id, from create_default_categories */
	categoryIdByName: Map<string, string>;
};

// ---- Deterministic RNG helpers ---------------------------------------------

function mulberry32(seed: number): () => number {
	let a = seed >>> 0;
	return () => {
		a |= 0;
		a = (a + 0x6d2b79f5) | 0;
		let t = Math.imul(a ^ (a >>> 15), 1 | a);
		t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	};
}

const pick = <T>(rng: () => number, arr: T[]): T => arr[Math.floor(rng() * arr.length)];
const randInt = (rng: () => number, min: number, max: number): number =>
	min + Math.floor(rng() * (max - min + 1));
const money = (rng: () => number, min: number, max: number): number =>
	Math.round((min + rng() * (max - min)) * 100) / 100;
const iso = (year: number, month: number, day: number): string =>
	`${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
const uuid = (): string => crypto.randomUUID();

// ---- Generator --------------------------------------------------------------

/** Months to populate: all of 2025 + Jan–Jul 2026 (today = 2026-07-19). */
const MONTHS: Array<{ year: number; month: number }> = [
	...Array.from({ length: 12 }, (_, i) => ({ year: 2025, month: i + 1 })),
	...Array.from({ length: 7 }, (_, i) => ({ year: 2026, month: i + 1 }))
];

export function generateDemoData(ctx: GeneratorContext): DemoData {
	const rng = mulberry32(0x5eed_1234);
	const { familyId, ownerId, memberId, categoryIdByName } = ctx;

	const transactions: TransactionRecord[] = [];
	const receipts: ReceiptRecord[] = [];
	const expenseCategories: ExpenseCategoryRecord[] = [];

	const catId = (name: string): string | undefined => categoryIdByName.get(name.toLowerCase());

	/** Build one receipt (+ optional matched transaction + category assignment). */
	function addReceipt(opts: {
		userId: string;
		date: string;
		merchant: string;
		amount: number | null;
		categoryName?: string;
		matched?: boolean;
		suspicious?: boolean;
		splitGroupId?: string | null;
		currency?: string;
		exchangeRate?: number | null;
	}): ReceiptRecord {
		const receiptId = uuid();
		let matchedTransactionId: string | null = null;

		// A matched receipt gets a paired transaction: same |amount|, date within 3 days.
		if (opts.matched && opts.amount != null && (opts.currency ?? 'CAD') === 'CAD') {
			const txnId = uuid();
			const shift = randInt(rng, 0, 2);
			const day = Number(opts.date.slice(8, 10));
			const txnDay = Math.max(1, day - shift);
			transactions.push({
				id: txnId,
				family_id: familyId,
				transaction_date: `${opts.date.slice(0, 8)}${String(txnDay).padStart(2, '0')}`,
				vendor_name: opts.merchant,
				amount: -opts.amount,
				credit_card_type: pick(rng, CREDIT_CARD_TYPES),
				excluded: false
			});
			matchedTransactionId = txnId;
		}

		const useCard = rng() < 0.7;
		receipts.push({
			id: receiptId,
			user_id: opts.userId,
			family_id: familyId,
			receipt_image_path: null,
			transaction_date: opts.date,
			total_amount: opts.amount,
			tax: opts.amount != null && rng() < 0.5 ? Math.round(opts.amount * 0.115 * 100) / 100 : null,
			merchant_name: opts.merchant,
			credit_card_name: useCard ? pick(rng, CARD_NAMES) : null,
			credit_card_last_4: useCard ? String(randInt(rng, 1000, 9999)) : null,
			currency: opts.currency ?? 'CAD',
			exchange_rate_to_cad: opts.exchangeRate ?? null,
			matched_transaction_id: matchedTransactionId,
			suspicious_date: opts.suspicious ?? false,
			split_group_id: opts.splitGroupId ?? null,
			original_filename: null
		});

		// Assign a category unless told to leave it Uncategorized.
		if (opts.categoryName) {
			const id = catId(opts.categoryName);
			if (id) {
				expenseCategories.push({
					receipt_id: receiptId,
					category_id: id,
					categorization_source: rng() < 0.8 ? 'auto' : 'manual'
				});
			}
		}
		return receipts[receipts.length - 1];
	}

	// --- Ordinary spend: 6–8 receipts/month across both users -----------------
	for (const { year, month } of MONTHS) {
		const count = randInt(rng, 6, 8);
		for (let i = 0; i < count; i++) {
			const entry = pick(rng, CATALOG);
			addReceipt({
				userId: rng() < 0.6 ? ownerId : memberId,
				date: iso(year, month, randInt(rng, 1, 28)),
				merchant: pick(rng, entry.merchants),
				amount: money(rng, entry.min, entry.max),
				categoryName: entry.category,
				matched: rng() < 0.6 // ~60% matched to a transaction
			});
		}
	}

	// --- Edge-case showcase (recent months, so visible without scrolling) -----

	// 1. Split receipt: one $210 Costco run split three ways.
	const splitId = uuid();
	addReceipt({ userId: ownerId, date: '2026-06-12', merchant: 'Costco Wholesale', amount: 90, categoryName: 'Groceries', splitGroupId: splitId }); // prettier-ignore
	addReceipt({ userId: ownerId, date: '2026-06-12', merchant: 'Costco Wholesale', amount: 70, categoryName: 'House Maintenance and Repairs', splitGroupId: splitId }); // prettier-ignore
	addReceipt({ userId: ownerId, date: '2026-06-12', merchant: 'Costco Wholesale', amount: 50, categoryName: 'Personal Care', splitGroupId: splitId }); // prettier-ignore

	// 2. A clean matched pair (equal amount, same date) for the reconciliation shot.
	addReceipt({ userId: memberId, date: '2026-07-11', merchant: 'The Keg', amount: 128.4, categoryName: 'Meals and Drinks Out', matched: true }); // prettier-ignore

	// 3. Unmatched standalone receipt (no transaction).
	addReceipt({ userId: memberId, date: '2026-07-14', merchant: 'Airbnb', amount: 315.0, categoryName: 'Travel - Accommodations' }); // prettier-ignore

	// 4. Duplicate pair: two identical receipts (same amount + date + merchant).
	addReceipt({ userId: ownerId, date: '2026-07-02', merchant: 'Shell', amount: 72.5, categoryName: 'Car - Gas' }); // prettier-ignore
	addReceipt({ userId: ownerId, date: '2026-07-02', merchant: 'Shell', amount: 72.5, categoryName: 'Car - Gas' }); // prettier-ignore

	// 5. Suspicious / old date (>42 days before 2026-07-19).
	addReceipt({ userId: ownerId, date: '2026-05-10', merchant: 'Home Depot', amount: 156.3, categoryName: 'House Maintenance and Repairs', suspicious: true }); // prettier-ignore

	// 6. Future-dated receipt → "Upcoming" badge.
	addReceipt({ userId: memberId, date: '2026-08-20', merchant: 'Air Canada', amount: 640.0, categoryName: 'Travel - Airfare', suspicious: true }); // prettier-ignore

	// 7. Amount-not-read: total_amount null → "⚠ Amount not read".
	addReceipt({ userId: ownerId, date: '2026-07-08', merchant: 'Metro', amount: null, categoryName: 'Groceries' }); // prettier-ignore

	// 8. Foreign currency: USD with an exchange rate → estimated-CAD display.
	addReceipt({ userId: memberId, date: '2026-06-28', merchant: 'Amazon.com', amount: 49.99, categoryName: 'Entertainment', currency: 'USD', exchangeRate: 1.37 }); // prettier-ignore

	// 9. Uncategorized receipts (no expense_categories row) → Uncategorized block.
	addReceipt({ userId: ownerId, date: '2026-07-06', merchant: 'Village Market', amount: 41.2 });
	addReceipt({ userId: memberId, date: '2026-07-09', merchant: 'Corner Store', amount: 18.75 });

	// --- Standalone transactions (unmatched side + refund + excluded) ---------

	// Refund / credit: positive amount → green in the UI.
	transactions.push({ id: uuid(), family_id: familyId, transaction_date: '2026-07-05', vendor_name: 'Amazon.ca Refund', amount: 64.99, credit_card_type: 'American Express', excluded: false }); // prettier-ignore

	// Excluded (soft-deleted) transaction → greyed "(excluded)".
	transactions.push({ id: uuid(), family_id: familyId, transaction_date: '2026-06-20', vendor_name: 'Interac e-Transfer', amount: -500, credit_card_type: 'TD Bank', excluded: true }); // prettier-ignore

	// A few plain unmatched transactions for the reconciliation "unmatched" column.
	const unmatchedVendors = ['Uber', 'LCBO', 'Presto Transit', 'Apple.com/bill'];
	for (const vendor of unmatchedVendors) {
		transactions.push({
			id: uuid(),
			family_id: familyId,
			transaction_date: iso(2026, 7, randInt(rng, 1, 15)),
			vendor_name: vendor,
			amount: -money(rng, 12, 90),
			credit_card_type: pick(rng, CREDIT_CARD_TYPES),
			excluded: false
		});
	}

	return { transactions, receipts, expenseCategories };
}

